# tiling search: tiles = complete 2x2 squares + L-trominoes (3 cells in a 2x2 bbox missing one corner)
def tiles(g):
    H,W=len(g),len(g[0])
    T=[]
    for i in range(H-1):
        for j in range(W-1):
            cells=[(i,j),(i,j+1),(i+1,j),(i+1,j+1)]
            if all(g[r][c]==8 for r,c in cells):
                T.append(('sq',cells))
            for m_ in [(0,0),(0,1),(1,0),(1,1)]:
                if m_ not in [(r-r0,c-c0) for r,c in cells for r0,c0 in [(None,None)]]: pass
                # L missing corner m_: cells = 2x2 minus m_
                rest=[c for c in cells if c!=(i+m_[0],j+m_[1])]
                if all(g[r][c]==8 for r,c in rest):
                    T.append(('l'+str(m_),set(rest)))
    return T
def back(idx, covered, out):
    if idx==len(cells): return True
    for t in T[idx:]:
        typ,cl=t
        if cl&covered: continue
        covered|=cl; out[typ]=cl
        if back(idx+1, covered, out): return True
        covered-=cl; del out[typ]
    return False
