    # just count combos that cover: need exact cover
    cnt=sum(1 for c in __import__('itertools').combinations(range(len(T)), r) for r in range(len(T))+1 if set().union(*(T[i][1] for i in c))==cells and len(set())==0)
    print('  covering combos:',cnt)

